import openpyxl

# Coefficients for Dots formula
coeff = {
    'M': {'a': 0.00000109305, 'b': -0.000739129, 'c': 0.783466017},
    'F': {'a': 0.00000248035, 'b': -0.001254805, 'c': 0.822295605}
}

def dots_coeff(total, bw, sex):
    if sex not in coeff:
        return None
    a = coeff[sex]['a']
    b = coeff[sex]['b']
    c = coeff[sex]['c']
    denominator = a * bw * bw + b * bw + c
    if denominator == 0:
        return None
    return total * (500 / denominator)

wb = openpyxl.load_workbook('/root/data/openipf.xlsx')
data_sheet = wb['Data']
dots_sheet = wb['Dots']

# Clear the Dots sheet (optional)
dots_sheet.delete_rows(1, dots_sheet.max_row)

# Columns to copy from Data (by header name)
copy_headers = ['Name', 'Sex', 'BodyweightKg', 'Best3SquatKg', 'Best3BenchKg', 'Best3DeadliftKg']
