header_to_col = {}
for col in range(1, data_sheet.max_column + 1):
    val = data_sheet.cell(row=1, column=col).value
    if val in copy_headers:
        header_to_col[val] = col

# Write headers to Dots sheet
for idx, h in enumerate(copy_headers, start=1):
    dots_sheet.cell(row=1, column=idx, value=h)
# Add TotalKg and Dots headers
