# Process each data row
for row in range(2, data_sheet.max_row + 1):
    # Extract values
    vals = {}
    for h in copy_headers:
        col = header_to_col[h]
        vals[h] = data_sheet.cell(row=row, column=col).value

    # Write copied values to Dots sheet
    for idx, h in enumerate(copy_headers, start=1):
        dots_sheet.cell(row=row, column=idx, value=vals[h])

    # Compute TotalKg
    squat = vals['Best3SquatKg']
    bench = vals['Best3BenchKg']
    deadlift = vals['Best3DeadliftKg']
    if isinstance(squat, (int, float)) and isinstance(bench, (int, float)) and isinstance(deadlift, (int, float)):
        total = squat + bench + deadlift
    else:
        total = None
    dots_sheet.cell(row=row, column=len(copy_headers)+1, value=total)

    # Compute Dots
    bw = vals['BodyweightKg']
    sex = vals['Sex']
    if isinstance(total, (int, float)) and isinstance(bw, (int, float)) and sex in ('M', 'F'):
        dots_val = dots_coeff(total, bw, sex)
    else:
        dots_val = None
    dots_sheet.cell(row=row, column=len(copy_headers)+2, value=dots_val)

# Apply rounding to 3 decimal places for TotalKg and Dots columns
for row in range(2, dots_sheet.max_row + 1):
    for col in [len(copy_headers)+1, len(copy_headers)+2]:
        val = dots_sheet.cell(row=row, column=col).value
        if isinstance(val, (int, float)):
            dots_sheet.cell(row=row, column=col, value=round(val, 3))

wb.save('/root/data/openipf.xlsx')
print('Done')
